import java.util.*;
class Solution {
    public int singleNumber(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);
        for (int k : counts.keySet()) if (counts.get(k) == 1) return k;
        return 0;
    }
}

