class Solution {
    public int[] singleNumber(int[] nums) {
        int diff = 0;
        for (int x : nums) diff ^= x;
        diff &= -diff;
        int[] res = new int[2];
        for (int x : nums) {
            if ((x & diff) == 0) {
                res[0] ^= x;
            } else {
                res[1] ^= x;
            }
        }
        return res;
    }
}

