class Solution:
    def countPrimes(self, n: int) -> int:
        if n <= 2:
            return 0
        not_prime = [False] * n
        i = 2
        while i * i < n:
            if not not_prime[i]:
                for j in range(i * i, n, i):
                    not_prime[j] = True
            i += 1
        return sum(1 for x in range(2, n) if not not_prime[x])

